<script setup lang="ts">import{ref}from'vue';import{useI18n}from'vue-i18n';import AccountShell from'../components/AccountShell.vue';import{useAppStore}from'../stores/app';const open=ref(false),store=useAppStore(),{t}=useI18n();const addresses=ref([{name:'示例用户',phone:'130 •••• 8404',region:'china',line:'广东省深圳市宝安区共乐发展科技大厦',def:true},{name:'Alex Rivers',phone:'+81 90 •••• 2233',region:'japan',line:'東京都渋谷区神宮前 1-2-3, 150-0001',def:false}]);function save(){open.value=false;store.toast(t('addresses.saved'))}function setDefault(index:number){addresses.value.forEach(item=>item.def=false);addresses.value[index].def=true;store.toast(t('addresses.defaultSaved'))}</script>
<template><AccountShell><div class="title"><div><span class="eyebrow">{{t('eyebrow.addressBook')}}</span><h1>{{t('addresses.title')}}</h1><p>{{t('addresses.subtitle')}}</p></div><button class="btn btn-primary" @click="open=true">{{t('addresses.add')}}</button></div><div class="address-list"><article v-for="(address,index) in addresses" :key="address.phone" class="address-card card"><div class="location">⌖</div><div><span class="eyebrow">{{t(`addresses.${address.region}`)}}</span><h2>{{index===0?t('addressDemo.name'):address.name}} <span v-if="address.def" class="pill gold">{{t('addresses.default')}}</span></h2><p>{{address.phone}}</p><p>{{index===0?t('addressDemo.chinaLine'):address.line}}</p><small>{{t('addresses.snapshot')}}</small></div><div class="address-actions"><button class="btn btn-outline" @click="open=true">{{t('common.edit')}}</button><button v-if="!address.def" class="btn btn-outline" @click="setDefault(index)">{{t('addresses.setDefault')}}</button><button class="btn btn-danger" :disabled="address.def">{{t('common.remove')}}</button></div></article></div><div class="region-tip card"><b>{{t('addresses.regionsTitle')}}</b><span>{{t('addresses.regions')}}</span><p>{{t('addresses.threshold')}}</p></div><div v-if="open" class="drawer-mask" @click.self="open=false"><aside class="drawer"><div class="drawer-head"><div><span class="eyebrow">{{t('eyebrow.shippingAddress')}}</span><h2>{{t('addresses.new')}}</h2></div><button @click="open=false">×</button></div><form @submit.prevent="save"><div class="field"><label>{{t('addresses.country')}}</label><select><option>{{t('addresses.china')}}</option><option>{{t('addresses.japan')}}</option><option>{{t('addresses.macau')}}</option></select></div><div class="two"><div class="field"><label>{{t('addresses.recipient')}}</label><input required :value="t('addressDemo.name')"></div><div class="field"><label>{{t('addresses.phone')}}</label><input required value="13042038404"></div></div><div class="field"><label>{{t('addresses.address')}}</label><input required :placeholder="t('addresses.street')"></div><div class="two"><div class="field"><label>{{t('addresses.city')}}</label><input required :value="t('addressDemo.city')"></div><div class="field"><label>{{t('addresses.province')}}</label><input required :value="t('addressDemo.province')"></div></div><div class="field"><label>{{t('addresses.postal')}}</label><input required value="518000"></div><label class="check"><input type="checkbox"> {{t('addresses.setDefault')}}</label><div class="drawer-actions"><button type="button" class="btn btn-outline" @click="open=false">{{t('common.cancel')}}</button><button class="btn btn-primary">{{t('addresses.save')}}</button></div></form></aside></div></AccountShell></template>
<style scoped>.title{display:flex;justify-content:space-between;align-items:end;margin-bottom:24px}.title h1{margin:5px 0}.title p{margin:0;color:var(--muted)}.address-list{display:grid;gap:16px}.address-card{padding:25px;display:grid;grid-template-columns:60px 1fr auto;gap:20px;align-items:center}.location{width:55px;height:55px;border-radius:50%;display:grid;place-items:center;background:#fff4a5;color:var(--brown);font-size:26px}.address-card h2{font-size:18px;margin:7px 0}.address-card p{margin:5px 0;font-size:13px}.address-card small{color:var(--muted)}.address-actions{display:grid;grid-template-columns:1fr 1fr;gap:7px}.address-actions .btn-danger{grid-column:1/-1}.region-tip{display:flex;align-items:center;gap:20px;margin-top:18px;padding:20px}.region-tip span{color:var(--brown);font-weight:700}.region-tip p{margin-left:auto;font-size:12px;color:var(--muted)}.drawer-mask{position:fixed;inset:0;background:rgba(0,0,0,.4);z-index:60}.drawer{position:absolute;right:0;top:0;bottom:0;width:min(520px,100%);background:white;padding:30px;overflow:auto}.drawer-head{display:flex;justify-content:space-between}.drawer-head h2{margin:5px 0 25px}.drawer-head button{border:0;background:#f3f3ef;width:36px;height:36px;border-radius:50%;font-size:20px}.drawer form{display:grid;gap:18px}.two{display:grid;grid-template-columns:1fr 1fr;gap:14px}.check{font-size:13px}.drawer-actions{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:15px}@media(max-width:767px){.title{display:block}.title .btn{margin-top:16px}.address-card{grid-template-columns:45px 1fr;padding:18px}.location{width:44px;height:44px}.address-actions{grid-column:1/-1;grid-template-columns:1fr 1fr 1fr}.address-actions .btn-danger{grid-column:auto}.region-tip{display:grid;gap:7px}.region-tip p{margin:0}.two{grid-template-columns:1fr}}</style>
